#include <iostream>
#include <vector>

using namespace std;

int m, n;
int maze[20][20]; // 迷宫地图，0表示墙，1表示路
int startX, startY;
int endX, endY;
bool foundPath = false;

// 记录路径，最多有 m*n 个点
vector<pair<int, int>> path;

// 方向数组：左、上、右、下
int dx[] = {0, -1, 0, 1};
int dy[] = {-1, 0, 1, 0};

void printPath() {
    for (int i = 0; i < path.size(); ++i) {
        cout << "(" << path[i].first << "," << path[i].second << ")";
        if (i != path.size() - 1) {
            cout << "->";
        }
    }
    cout << endl;
}

void dfs(int x, int y) {
    // 到达终点，输出路径
    if (x == endX && y == endY) {
        printPath();
        foundPath = true;
        return;
    }

    // 按照左、上、右、下的顺序探索
    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        // 检查边界和是否可通行
        if (nx >= 1 && nx <= m && ny >= 1 && ny <= n && maze[nx][ny] == 1) {
            // 标记为已访问
            maze[nx][ny] = 0;
            path.emplace_back(nx, ny);

            dfs(nx, ny);

            // 回溯，恢复状态
            path.pop_back();
            maze[nx][ny] = 1;
        }
    }
}

int main() {
    cin >> m >> n;
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= n; ++j) {
            cin >> maze[i][j];
        }
    }
    cin >> startX >> startY;
    cin >> endX >> endY;

    // 起点标记为已访问
    maze[startX][startY] = 0;
    path.emplace_back(startX, startY);

    dfs(startX, startY);

    if (!foundPath) {
        cout << -1 << endl;
    }

    return 0;
}
